typedef struct type_object {
    const char *id;
    int         base_health;
    const char *(*attack)(const struct object *);
} type_object;
typedef struct object { const type_object *type; int health; } object;
object *object_create(const registry *r, const char *id) {
    const type_object *t = registry_find(r, id);   /* NULL -> fail fast */
    object *o = malloc(sizeof *o);
    o->type = t; o->health = t->base_health;       /* copy type defaults */
    return o;
}
